{
  "findings": [
    {
      "check_id": "AVD-AWS-0178",
      "title": "VPC Flow Logs is not enabled for VPC",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "Without VPC flow logs, you risk not having enough information about network traffic flow to investigate incidents or identify security issues."
    },
    {
      "check_id": "CKV2_AWS_11",
      "title": "Ensure VPC flow logging is enabled in all VPCs",
      "resource": "aws_vpc.changeme_aws_vpc_simple",
      "severity": "MEDIUM",
      "explanation": "VPC flow logging is not enabled in the VPC changeme_aws_vpc_simple."
    }
  ],
  "patched_code": "resource \"aws_vpc\" \"changeme_aws_vpc_simple\" {\n  cidr_block = \"10.1.0.0/16\"\n}\n\nresource \"aws_flow_log\" \"changeme_aws_vpc_simple_flow_log\" {\n  vpc_id         = aws_vpc.changeme_aws_vpc_simple.id\n  traffic_type   = \"ALL\"\n  log_destination = \"${aws_vpc.changeme_aws_vpc_simple.arn}/flow-logs\"\n}\n\nresource \"aws_cloudwatch_log_group\" \"changeme_aws_vpc_simple_flow_log_group\" {\n  name = \"${aws_vpc.changeme_aws_vpc_simple.arn}/flow-logs\"\n}",
  "fix_summary": "Added aws_flow_log and aws_cloudwatch_log_group resources to enable VPC flow logging for the created VPC."
}
